CREATE TABLE "FixedCostSheet" (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "FixedCostEntry" (id TEXT PRIMARY KEY,"sheetId" TEXT NOT NULL REFERENCES "FixedCostSheet"(id) ON DELETE RESTRICT,month TEXT NOT NULL,date TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('FIXED','VARIABLE')),concept TEXT NOT NULL,category TEXT NOT NULL DEFAULT '',country TEXT NOT NULL DEFAULT '',location TEXT NOT NULL DEFAULT '',person TEXT NOT NULL DEFAULT '',amount DECIMAL(14,2) NOT NULL CHECK(amount>=0),currency TEXT NOT NULL,paid BOOLEAN NOT NULL DEFAULT false,notes TEXT NOT NULL DEFAULT '',"seriesId" TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,"createdById" TEXT NOT NULL,"updatedById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("seriesId",month));
CREATE INDEX "FixedCostEntry_month_sheetId_idx" ON "FixedCostEntry"(month,"sheetId");
CREATE TABLE "FixedCostGrant" ("userId" TEXT PRIMARY KEY REFERENCES "User"(id) ON DELETE CASCADE,permission TEXT NOT NULL CHECK(permission IN ('VIEW','EDIT')),"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
